INSERT INTO `comentario` VALUES (1,'Vista privilegiada desde zona preferente. El escenario se ve completo sin ningún obstáculo. El sonido es espectacular, claramente la mejor ubicación del teatro.',5.0,NULL,2,1,1,NULL),(2,'Fila 2, columna central. No puedes pedir más. Visibilidad perfecta, se escucha todo con una nitidez increíble. Merece cada euro del precio.',5.0,NULL,3,2,1,NULL),(3,'Zona A primera fila, sensación inmersiva total. Los actores casi los puedes tocar. Muy recomendable para musicals donde quieres ver todos los detalles.',4.5,NULL,4,3,1,NULL),(4,'Excelente visibilidad desde aquí. La iluminación del escenario se aprecia perfectamente. Butacas muy cómodas, espacio para las piernas suficiente.',4.5,NULL,5,4,1,NULL),(5,'Primera vez en zona preferente y quedé impresionada. El ángulo es ideal, sin tener que girar el cuello. Los efectos especiales se ven de forma espectacular desde aquí.',5.0,NULL,6,5,1,NULL),(6,'Zona B fila 4, buena relación calidad-precio. Se ve todo perfectamente, algo más lejos que preferente pero sin perder detalle. El sonido llega con mucha claridad.',4.0,NULL,7,36,1,NULL),(7,'Platea central, vista estupenda. A esta distancia se pierde algo de detalle facial pero se gana perspectiva del conjunto del escenario. Muy satisfecho.',4.0,NULL,8,37,1,NULL),(8,'Columna lateral en zona B, se ve el escenario un poco en ángulo pero sin problemas. El precio es justo para lo que ofrece. Butacas cómodas.',3.5,NULL,2,38,1,NULL),(9,'Vista correcta desde platea. El escenario completo, el sonido envolvente. Para el precio que tiene es una opción muy recomendable. Repetir seguro.',4.0,NULL,3,39,1,NULL),(10,'Fila 6 zona B, algo lejos pero se compensa con una vista panorámica del escenario completo. Para obras de teatro clásico es ideal porque ves la escenografía entera.',3.5,NULL,4,40,1,NULL),(11,'Anfiteatro fila 7. La distancia es notable pero el precio es imbatible. Para conciertos es una opción fantástica porque el sonido sube muy bien. Para teatro prefiero platea.',3.5,NULL,5,77,1,NULL),(12,'Zona C correcta para el precio. Se ve todo aunque pequeño. Con binoculares sería perfecta. Para conciertos de música clásica el sonido es magnífico incluso desde aquí arriba.',3.0,NULL,6,78,1,NULL),(13,'Última fila anfiteatro. Punto de vista único, ves el espectáculo desde arriba y la perspectiva es muy diferente. Para ópera es bonito ver los movimientos corales desde esta altura.',3.5,NULL,7,79,1,NULL),(14,'Columna 8 zona C, vista ligeramente lateral. Nada grave pero se nota algo. El precio hace que valga la pena completamente. Repetiría si el presupuesto es ajustado.',3.0,NULL,8,80,1,NULL),(15,'Anfiteatro central fila 8. Lejos sí, pero con buen ángulo. La acústica del teatro es excelente y el sonido llega perfectamente. Para el precio, imposible quejarse.',3.5,NULL,2,81,1,NULL),(16,'La vista fenomenal desde aqui',0.0,'storage/images/comentarios/bOFhe2Rabkhl3OdbFh89Vbqsl2hPgYKnikSb1s32.jpg',1,404,NULL,NULL),(17,'La vista fenomenal desde aqui',5.0,'storage/images/comentarios/M8vuAL3LAnynPuiZB3K5cIFDdRl1khTPlE5PDfq0.jpg',1,404,NULL,NULL),(18,'prueba',5.0,'storage/images/comentarios/fHsdXo23yW9EoluqzPxQxksCZb3XTnIAwY4kaYOS.jpg',1,392,NULL,NULL),(19,'Que ganas tengo de este evento',NULL,NULL,1,NULL,7,NULL),(20,'yo tambien',NULL,NULL,1,NULL,7,19),(21,'Una gran obra y las vistas fabulosas',4.0,'storage/images/comentarios/WM80h09kblYXss5hrdqy89pOiCU5Un2gVAiomQV1.jpg',1,17,9,NULL);
/*!40000 ALTER TABLE `comentario` ENABLE KEYS */;
UNLOCK TABLES;

