INSERT INTO `evento` VALUES (1,'El Fantasma de la Ópera','activo','4.8','C/ Ramos Marín s/n, Málaga','Musical','El clásico de Andrew Lloyd Webber vuelve a los escenarios en una producción espectacular con los mejores efectos especiales. Una historia de amor, obsesión y música que te dejará sin aliento.','https://picsum.photos/seed/fantasma-opera/800/450','02:30:00','2025-05-15','Musical',1),(2,'La Traviata','activo','4.9','La Rambla 51-59, Barcelona','Ópera','La ópera más representada del mundo de Giuseppe Verdi. Una historia de amor imposible entre Violetta, cortesana parisina, y el joven Alfredo. Una producción del Gran Teatro del Liceu con voces de primera categoría mundial.','https://picsum.photos/seed/la-traviata/800/450','02:45:00','2025-05-22','Ópera',3),(3,'Chicago el Musical','activo','4.6','C/ Ramos Marín s/n, Málaga','Musical','Broadway llega a Málaga. Crimen, corrupción, jazz y showbiz en el Chicago de los años 20. Con los temas más icónicos como \"All That Jazz\" y \"Roxie\". Una noche que no olvidarás.','https://picsum.photos/seed/chicago-musical/800/450','02:15:00','2025-06-07','Musical',1),(4,'Carmina Burana','activo','4.7','C/ Príncipe de Vergara 146, Madrid','Concierto','La Orquesta y Coro Nacional de España interpreta la obra magna de Carl Orff. Una experiencia musical sin igual con más de 200 músicos y cantantes en escena. La obertura O Fortuna en todo su esplendor.','https://picsum.photos/seed/carmina-burana/800/450','01:45:00','2025-06-14','Clásica',2),(5,'Noche de Flamenco','activo','4.5','Paseo de Colón 22, Sevilla','Concierto','Una noche mágica con los mejores exponentes del flamenco contemporáneo. Baile, cante jondo y guitarra española en el teatro más emblemático de Sevilla. Arte puro en estado bruto.','https://picsum.photos/seed/noche-flamenco/800/450','02:00:00','2025-06-21','Flamenco',4),(6,'Hamlet','activo','4.7','La Rambla 51-59, Barcelona','Teatro','La tragedia más universal de Shakespeare en una versión contemporánea dirigida por uno de los directores más reconocidos del teatro europeo. Una reflexión sobre el poder, la traición y la locura.','https://picsum.photos/seed/hamlet-shakespeare/800/450','02:30:00','2025-07-05','Drama',3),(7,'Concierto de Jazz: Miles Davis Tribute','activo','4.4','C/ Príncipe de Vergara 146, Madrid','Concierto','Homenaje al genio del jazz en el centenario de su nacimiento. La Iberian Jazz Orchestra interpreta los grandes temas de Kind of Blue, Bitches Brew y otras obras maestras del artista más influyente del jazz moderno.','https://picsum.photos/seed/jazz-tribute-madrid/800/450','01:50:00','2025-07-12','Jazz',2),(8,'La Casa de Bernarda Alba','activo','4.6','Paseo de Colón 22, Sevilla','Teatro','La obra cumbre de Federico García Lorca en una producción que ha recorrido los principales teatros de Europa. La historia de opresión, deseo y libertad de cinco mujeres bajo el yugo de una madre autoritaria.','https://picsum.photos/seed/bernarda-alba/800/450','01:45:00','2025-07-19','Drama',4),(9,'La Perdida de la Fe','finalizado','0','Por determinar','Teatro','Una obra ficticia','images/eventos/1776729897_2316808.jpeg','04:05:00','2026-04-02','Drama',1);
/*!40000 ALTER TABLE `evento` ENABLE KEYS */;
UNLOCK TABLES;

